/**
 * A steward re-settles a settled claim: its due is frozen again at the figure it would have today as an open
 * claim bound by no statement (today's rates, grades and floor, with the late charge it has gained by today; a
 * correction gains none). Refused unless the user is a steward, unless it is settled, and in a closed period.
 */
@Transactional
public Claim resettle(String by, String sheetId, Long id) {
    if (!settings.isSteward(sheetId, by)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
    }
    Claim claim = lockedClaim(sheetId, id);
    if (claim.getStatus() != ClaimStatus.SETTLED) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
    }
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    Person person = person(sheetId, claim.getPersonId());
    BigDecimal old = claim.getSettledDue();
    BigDecimal fixed = liveDue(rateFigure(sheetId, person, claim), claim, person, sheets.load(sheetId), true);
    claim.setSettledDue(fixed);
    logStatus(by, sheetId, person, claim);
    Claim saved = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_RESETTLED", by, person, saved) + " old=" + text(old) + " new="
            + text(fixed));
    watches.notifyWatchers(by, sheetId, person, saved.getNumber());
    rollup.recordChanges(by, sheetId, before);
}

public boolean isStated() {
    return stated;
}

/**
 * Whether the claim's figure is bound by its person's last statement: stated (a pending claim is bound like any
 * other claim that counts).
 */
public boolean isBound() {
    return stated;
}

public BigDecimal getStatedDue() {
    return statedDue;
}

/** Binds the claim to the figure (null for n/a) until the next statement. */
public void bind(BigDecimal figure) {
    this.stated = true;
    this.statedDue = figure;
}

/** Frees the claim: its due is live again. */
public void unbind() {
    this.stated = false;
    this.statedDue = null;
}

public List<ClaimLogEntry> getLog() {
    holds.add(new DatedHold(from, to, madeOn));
}

/**
 * Whether the claim counts toward the person's live totals: one whose status counts, except an open one dated
 * within a hold that no statement binds, or once the person's retirement date is reached on the sheet's today, and
 * one deferred on the sheet's today.
 */
public boolean countsLive(Claim claim, LocalDate today) {
    return claim.getStatus().counts() && !claim.isDeferredOn(today)
            && !(claim.getStatus().isOpen() && !claim.isBound()
            && (holds.stream().anyMatch(h -> h.covers(claim.getDate())) || isRetiredOn(today)));
}

/**
 * Whether the claim counts toward the person's figure for a period ending on the day: one whose status at the end
 * of that day counts, left out as the live rules say when deferred on the sheet's today or held.
 */
public boolean countsAtEndOf(Claim claim, LocalDate end, LocalDate today) {
    ClaimStatus then = claim.statusAtEndOf(end);
    return then != null && then.counts() && !claim.isDeferredOn(today)
            && !(claim.getStatus().isOpen() && !claim.isBound()
            && (holds.stream().anyMatch(h -> h.covers(claim.getDate())) || isRetiredOn(today)));
}

/** The version of the person as stored, raised on each save. */

